import re,os,sys,collections
sys.path.insert(0,os.environ.get("RSCK_DIR","/home/deck/semio/.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️11/☀️01/NORM-COMPLETE-VISUAL-EUROCODE-PLUGINS/🗑️generated/compile-review-a"))
from rsck import clean
T=sys.argv[1]
defined=set(open(T+'/defined-fns.txt').read().split())
# methods generated by derives/macros
extra=set('clone clone_from fmt eq ne cmp partial_cmp hash default to_value from_value into try_into from try_from as_ref as_mut borrow borrow_mut to_owned to_string into_iter iter next drop deref deref_mut index index_mut add sub mul div neg not rem'.split())
defined|=extra
res=collections.defaultdict(list)
for a in sys.argv[2:]:
    for dp,dn,fn in os.walk(a):
        dn[:]=[x for x in dn if x not in('node_modules','target','.git')]
        for f in fn:
            if not f.endswith('.rs'): continue
            p=os.path.join(dp,f)
            try: s=clean(open(p,encoding='utf8').read())
            except: continue
            for m in re.finditer(r'\.\s*([a-z_][a-z_0-9]*)\s*(?:::<[^>]*>)?\s*\(',s):
                n=m.group(1)
                if n not in defined:
                    res[n].append('%s:%d'%(p.replace('/home/deck/semio/✏️s/🔌️plugins/📕️norm/',''),s.count('\n',0,m.start())+1))
for n,l in sorted(res.items()):
    print(n,len(l),l[0][-110:])
